import assert from'node:assert/strict';import facts from'./legacy-2018-pm-members-facts.json';
const attrs=(s:string)=>Object.fromEntries([...s.matchAll(/([\w:-]+)="([^"]*)"/g)].map(m=>[m[1],m[2]]));
const decode=(s:string)=>s.replaceAll('&amp;','&').replaceAll('&lt;','<').replaceAll('&gt;','>').replaceAll('&#x27;',"'").replaceAll('&quot;','"');
const texts=(s:string):(Record<string,string>&{text:string})[]=>[...s.matchAll(/<text\b([^>]*)>([^<]*)<\/text>/g)].map(m=>({...attrs(m[1]),text:decode(m[2])}));
export function readLegacy2018MembersSvg(svg:string,profile:string,values:readonly number[]){
 assert(['legacy-2018-members-tables','legacy-2018-members-sql-scaffold'].includes(profile));assert(svg.includes('role="img"'));const desc=decode(svg.match(/<desc[^>]*>([\s\S]*?)<\/desc>/)![1]);assert(desc.length>30);
 if(profile.endsWith('tables')){assert.equal(values.length,2);const geometry=[[40,60,180,230,270,420],[40,320,180,230,150,220],[40,640,210,250],[550,640,200,230,240]];let cells=0,pks=0;const all=texts(svg);assert.equal([...svg.matchAll(/data-table=/g)].length,4);
 for(const [i,t]of facts.tables.entries()){const[x,y,...widths]=geometry[i],rows=[t.columns,...('shownData'in t?t.shownData:'knownPairs'in t?t.knownPairs:t.knownRows)!,t.columns.map(()=>'⋮')];assert(all.some(a=>a.text===t.title&&+a.x===x&&+a.y===y-18));for(const[rowIndex,row]of rows.entries())for(const[col,v]of row.entries()){const left=x+widths.slice(0,col).reduce((a,b)=>a+b,0),cx=left+widths[col]/2,cy=y+rowIndex*54+35;assert(all.some(a=>a.text===String(v)&&+a.x===cx&&+a.y===cy),`${t.title}/${rowIndex}/${col}:${v}`);assert(svg.includes(`x="${left}" y="${y+rowIndex*54}" width="${widths[col]}" height="54"`));cells++;}for(const label of t.primary){const col=t.columns.indexOf(label),left=x+widths.slice(0,col).reduce((a,b)=>a+b,0);assert(svg.includes(`data-primary="${col}" x1="${left+14}" x2="${left+widths[col]-14}" y1="${y+43}" y2="${y+43}"`));pks++;}}
 assert.equal(cells,50);assert.equal(pks,5);assert(desc.includes('東京都○○区□□□'));return{cells,primary:pks,rows:8,ellipsis:13};}
 assert.equal(values.length,3);const kind=values[0],id=['a','b','c'][kind];assert(id);const all=texts(svg),expected=kind===0?[[40,42,'SELECT DISTINCT 保護者表.保護者番号, 保護者表.保護者氏名'],[380,97,'a']]:kind===1?[[40,42,'SELECT イベント表.イベント名,'],[635,42,'b'],[80,100,'FROM 活動表, イベント表'],[80,156,'WHERE 活動表.イベント番号 = イベント表.イベント番号'],[80,212,'GROUP BY イベント表.イベント名']]:[[40,42,'DELETE FROM 保護者表'],[80,103,'WHERE'],[555,102,'c']];assert.equal(all.length,expected.length);for(const[x,y,t]of expected)assert(all.some(a=>+a.x===x&&+a.y===y&&a.text===t));const b=attrs(svg.match(/<rect\b([^>]*data-blank[^>]*)/)!?.[1]??'');assert.equal(b['data-blank'],id);assert.deepEqual([+b.x,+b.y,+b.width,+b.height],kind===0?[80,65,600,48]:kind===1?[525,10,220,48]:[180,70,750,48]);assert.equal(desc,`設問${kind+2}のSQL文。空欄${id}は一つ。\n${facts.scaffolds[id as keyof typeof facts.scaffolds]}`);return{kind:id,blank:1,visibleLines:expected.length};
}
